async (ev, el, s) => {
            ev.preventDefault()
            ev.stopImmediatePropagation()
            if (!s.parent.toUpdate) {
              return
            }
            try {
              const {
                id: memberId,
                newRole
              } = s.parent.toUpdate

              if (newRole) {
                // Call API to update member role
                await el.sdk.updateMemberRole(
                  s.root.projectId,
                  memberId,
                  newRole
                )

                s.parent.update({
                  memberRoleBeingEdited: null,
                  toUpdate: null,
                  successMessage: 'Member role updated successfully!'
                })

                // Refresh the table after a short delay
                setTimeout(async () => {
                  const result = await el.sdk.getProjectMembers(
                    s.root.projectId
                  )
                  s.parent.replace({
                    projectMembers: result.map((r) => ({
                      ...r,
                      id: r.user.id,
                      email: r.user.email,
                      name: r.user.name || r.user.email,
                      role: r.role
                    })) || []
                  })
                }, 500)
              }
            } catch (error) {
              s.parent.update({
                errorMessage: `Error: ${
                  error.message || 'Failed to update member role'
                }`,
                memberRoleBeingEdited: null,
                toUpdate: null
              })
            }
          }

