/add-custom-domain-modal.onSubmit:
(e, el, st, ctx) => {
    e.preventDefault()

    if (!st.domainName) {
      return
    }

    const urlParams = new URLSearchParams(ctx.window.location.search)
    const type = urlParams.get('type')

    if (!type) {
      return
    }

    const {
      root
    } = st
    if (root && root.domains && root.domains[type]) {
      if (root.domains[type].domain === st.domainName) {
        st.replace({
          validationMessage: `Domain with this name is already added for '${type}' environment`
        })
        return
      }
    }

    el.router(
      ctx.window.location.pathname.replace(
        '/add-domain',
        `/add-cname?type=${type}&domainName=${st.domainName}`
      ), el.getRoot()
    )
    ctx.window.location.reload()
  }

/add-cname-modal.onSubmit:
async (e, el, st, ctx) => {
    e.preventDefault()
    if (!st.cname) {
      return
    }

    const urlParams = new URLSearchParams(ctx.window.location.search)
    const type = urlParams.get('type')
    const domainName = urlParams.get('domainName')

    if (!type || !domainName) {
      return
    }

    const {
      root
    } = st
    if (root && root.domains && root.domains[type]) {
      if (root.domains[type].cname === st.cname) {
        st.replace({
          validationMessage: `CNAME with this name is already added for '${type}' environment`
        })
        return
      }
    }

    const domains = {}
    domains[type] = {
      domain: domainName,
      cname: st.cname
    }

    const response = await el.sdk.setProjectDomains(
      st.root.projectId,
      domains
    )

    if (response && response.success === true) {
      el.call('closeModal', el, st, ctx)
      st.root.update({
        domains
      })
    } else {
      el.call('openNotification', {
        title: 'Error message',
        message: `Could not create custom domain ${domainName}`,
        type: 'error'
      })
    }
  }

