(el, state) => {
        const s = state.parent.parse()
        const {
          searched,
          categoryFilter
        } = s
        if (!state.props) {
          return
        }
        let result = Object.values(state.props)
        if (searched) {
          result = result.filter(v => v.title.includes(searched))
        }
        if (categoryFilter) {
          result = result.filter(
            v => v.categoryType && v.categoryType.includes(categoryFilter)
          )
        }
        // eslint-disable-next-line consistent-return
        return result
      }

