PropertyItem.props:
(el, s) => {
      const activeRow = el.call('getPropertyTransition', 'activeRow')
      const activeFromUrlHash = window.location.hash === `#${s.title}-property`
      const isActive = s.isActive || (s.isActive !== false && activeFromUrlHash)
      const isActiveRow = isActive ? activeRow : {
        margin: '0',
        cursor: 'default',
        background: 'transparent 0',
        '@dark': {
          background: 'transparent 0'
        },
        '@light': {
          background: 'transparent 0'
        }
      }
      return {
        isActive,
        columns: '1.65fr 1.8fr 5fr 6fr',
        minHeight: 'D3',
        fontWeight: '400',
        overflow: 'hidden',
        fontSize: 'Z2',
        textDecoration: 'none',
        round: '0',
        padding: 'A A1 -',
        minWidth: 'H2',

        ':not(:first-child)': {
          '@dark': {
            border: '--color-line-highlight-dark, solid'
          },
          '@light': {
            border: '--color-line-highlight-light, solid'
          },
          borderWidth: '1px 0 0'
        },

        transition: '100ms, 100ms, 350ms, 350ms',
        transitionProperty: 'background, opacity, margin, padding',
        opacity: '0.85',

        ...isActiveRow,
        ':focus': activeRow,
        ':hover': activeRow,

        onInit: (el, s) => {
          const isActive = s.title === window.location.hash.slice(1)
          if (isActive) {
            s.isActive = true
          }
        },

        onClick: (ev, el, s) => {
          if (s.isActive) return
          Object.values(el.parent.parse())
            .filter(v => v && v.state)
            .map(v => v.state && v.state.update({
              isActive: !s.isActive && s.title === v.state.title
            }))
          ev.preventDefault()
        }
      }
    }

functions.tutorialState:
function tutorialState() {
    const activeRoute = this.call('getLocationPath', 1) ?
      this.call('getLocationPath', 1).slice(1) :
      'default'
    const {
      TUTORIALS
    } = this.context.snippets
    const activeTutorial = TUTORIALS[activeRoute] || TUTORIALS.default
    const {
      title,
      data
    } = activeTutorial
    const activeStepData = data[this.state.activeStep || 0]
    // console.warn('activeStepData', activeStepData)
    const {
      code
    } = activeStepData
    const value = this.call('evalStringCodeUnsafe', code)

    return {
      data,
      activeStep: this.state.activeStep || 0,
      tutorialName: title,
      ...activeStepData,
      code,
      value
    }
  }

