function STATE_METHODS() {
    const OPTIONS = {
      title: 'options',
      types: ['object'],
      description: ['Update options'],
      optional: true,
      subParams: [{
        title: 'isHoisted',
        types: ['boolean'],
        label: 'true',
        description: ['Flag that has been applied if state update hoists parent state update']
      }, {
        title: 'preventHoistElementUpdate',
        types: ['boolean'],
        label: 'false',
        description: ['If update hoists the parent state updates, this flag disables element update under parent state']
      }, {
        title: '...',
        description: ['All other options that you want to send to a receiver event.']
      }]
    }

    return [{
      id: 'update-method',
      title: 'update',
      description: 'Passing a new properties to update state',
      code: `{
  state: { isActive: 1 },
  onClick: (event, element, state) => state.update({
    isActive: state.active + 1
  }, { /* ...options */ })
}`,
      parameters: [{
        title: 'value',
        types: ['object', 'array'],
        description: ['Deep overwrite state value with objects or arrays'],
        optional: false
      }, OPTIONS]
    }, {
      id: 'set-method',
      title: 'set',
      description: 'Passing a new properties to set state (removes old values)',
      code: `{
  state: { /* data will be removed after 'set' */ },
  onClick: (event, element, state) => state.set({
    data: [...]
  }, { /* ...options */ })
}`,
      parameters: [{
        title: 'value',
        types: ['object', 'array'],
        description: ['Value to be set as state value'],
        optional: false
      }, OPTIONS]
    }, {
      id: 'reset-method',
      title: 'reset',
      description: 'Resetting state values with cloned existing ones.',
      code: `{
  onClick: (event, element, state) => state.reset({ /* ...options */ })
}`,
      parameters: [OPTIONS]
    }, {
      id: 'add-method',
      title: 'add',
      description: 'Passing a new properties to add state (removes old values)',
      code: `{
  state: ['item 1'],
  onClick: (event, element, state) => state.add('item 2', { /* ...options */ })
}`,
      parameters: [{
        title: 'value',
        types: ['any'],
        description: ['Add a new item to the state'],
        optional: false
      }, OPTIONS]
    }, {
