Breadcrumb.children:
(el, s, ctx) => {
    const routeArr = (window.top.location.pathname || window.location.pathname)
      .split('/')
      .slice(1)
    return routeArr
      .map((text, i) =>
        text === 'page' ? {
          href: '/pages',
          text: 'Page'
        } :
        el.getData('pages')[`/${text}`] ? {
          href: `/${routeArr.slice(0, i + 1).join('/')}`,
          text: `/${text}`
        } : {
          href: `/${routeArr.slice(0, i + 1).join('/')}`,
          text: i === 0 ? el.call('toTitleCase', text) : text
        }
      )
      .filter((_, k) => {
        const v = routeArr[k]
        return (
          !v.includes('-') && !v.includes('editor') && !v.includes('preview')
        )
      })
  }

SuggestionAction.onClick:
async (ev, el) => {
    ev.preventDefault()
    const href = el.call('resolveHref', el.props.href)
    await el.call('openModal', href?.replace(window.location.pathname, ''))
  }

