Iframe.src:
(el, s) => {
      const withAutoplay = (url) => {
        if (!url) return url

        const join = url.includes('?') ? '&' : '?'

        return (
          url +
          join +
          'autoplay=1&playsinline=1&controls=1&rel=0'
        )
      }

      return withAutoplay(s.activeVideo)
    }

