DraggableRow.onDragstart:
(e, el, s) => {
    e.stopPropagation()
    if (!el.parent.data) el.parent.data = {}
    el.setProps(el.props.dragstart)
    el.parent.data.fromIndex = el.key
    el.parent.data.state = s.parent
  }

DraggableRow.onDragover:
(e, el, s) => {
    e.stopPropagation()
    e.preventDefault()
    if (!el.parent.data) return
    return false
  }

DraggableRow.onDrop:
(e, el, s, ctx) => {
    if (!el.parent.data) return
    const isSame = el.parent.data.fromIndex === el.key
    const isSameGroup = el.parent.data.state === s.parent
    if (isSame || !isSameGroup) return
    if (e.stopPropagation) e.stopPropagation()
    const toIndex = el.key
    s.parent.apply((state) => ctx.utils.swapItemsInArray(state, el.parent.data.fromIndex, toIndex))
    el.setProps(el.props.drop)
  }

Draggable.onDragstart:
(e, el, s) => {
    e.stopPropagation()
    if (!el.parent.data) el.parent.data = {}
    el.setProps({
      transform: 'scale(0.97)',
      opacity: '0',
      isDragging: true
    })
    el.parent.data.fromIndex = el.key
    el.parent.data.state = s.parent
  }

Draggable.onDragover:
(e, el, s) => {
    e.stopPropagation()
    e.preventDefault()
    if (!el.parent.data) return
    return false
  }

Draggable.onDrop:
(e, el, s, ctx) => {
    if (!el.parent.data) return
    const isSame = el.parent.data.fromIndex === el.key
    const isSameGroup = el.parent.data.state === s.parent
    if (isSame || !isSameGroup) return
    if (e.stopPropagation) e.stopPropagation()
    const toIndex = el.key
    s.parent.apply((state) => ctx.utils.swapItemsInArray(state, el.parent.data.fromIndex, toIndex))
    el.setProps({
      opacity: '1',
      transform: 'none'
    })
  }

Draggable.onDragend:
(e, el, s) => {
    el.setProps({
      opacity: '1',
      transform: 'none',
      isDragging: false
    })
  }

SquareButton_moveUp.onClick:
(ev, el, s) => {
      const key = parseInt(s.__element.__ref.__state)
      s.parent.apply((state) => ctx.utils.swapItemsInArray(state, key, key - 1))
    }

SquareButton_moveDown.onClick:
(ev, el, s) => {
      const key = parseInt(s.__element.__ref.__state)
      s.parent.apply((state) => ctx.utils.swapItemsInArray(state, key, key + 1))
    }

SquareButton_plus.onClick:
(ev, el, s) => {
      const key = parseInt(s.__element.__ref.__state)
      s.parent.apply((state) => state.splice(key + 1, 0, {}))
    }

SquareButton_trash.onClick:
(ev, el, s) => {
      // const scopeData = s.parent.parent
      const key = s.__element.key
      if (window.confirm('Do you want to remove item?')) {
        s.parent.remove(key)
      }
    }

SquareButton_copy.onClick:
(ev, el, s) => {
      const key = parseInt(s.__element.__ref.__state)
      const value = ctx.utils.deepClone(s.parse())
      s.parent.apply((state) => state.splice(key + 1, 0, value))
    }

